function V({registerIndicator:b,nulls:g}){b({id:"oa-gkv",name:"Garman-Klass Volatility (GKV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"Period for smoothing the Garman-Klass estimator."},{key:"annualize",type:"boolean",label:"Annualize Volatility",default:!0,tooltip:"Annualize the volatility output."},{key:"annualPeriods",type:"number",label:"Annual Periods",default:252,min:1,max:1e5,step:1,tooltip:"Number of periods in a year for annualization (252 for daily, 52 for weekly)."}],plots:[{key:"gkv",type:"line",title:"GKV",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,i){const s=Math.max(1,Math.floor(Number(i.length)||20)),d=i.annualize!==!1,M=Math.max(1,Math.floor(Number(i.annualPeriods)||252)),k=.3862941611,F=1e-10,u=1/s,w=Math.sqrt(M);let t=NaN,e=NaN;const c=new Array(l.length).fill(NaN);for(let o=0;o<l.length;o++){const a=l[o],m=a.high,h=a.low,p=a.open,f=a.close;let n=NaN;if(m>0&&h>0&&p>0&&f>0){const v=Math.log(m),z=Math.log(h),P=Math.log(p),x=Math.log(f),A=.5*Math.pow(v-z,2),G=k*Math.pow(x-P,2);n=A-G}Number.isFinite(n)&&(t=Number.isFinite(t)?(t*(s-1)+n)/s:n,e=Number.isFinite(e)?(1-u)*e:1-u);const N=Number.isFinite(e)&&e>F&&Number.isFinite(t)?t/(1-e):t,r=Number.isFinite(N)?N:n;if(!Number.isFinite(r)||r<0)continue;const y=Math.sqrt(r);c[o]=d?y*w:y}return{gkv:g(c)}}})}export{V as default};
